import {safeParseWithLogging} from "@agenta/entities/shared"
import {getProjectsClient} from "@agenta/sdk/resources"
import {z} from "zod"

import {refreshSessionOutcome} from "./auth"

/** Mobile's own last-visited workspace/project, for `/m/` root resolution. */
export const LAST_CONTEXT_KEY = "agenta:mobile:last-context"

/** Desktop's continuity map ({[workspaceId]: projectId}) — read-only here. */
const DESKTOP_LAST_USED_KEY = "lastUsedProjectsByWorkspace"

export interface LastContext {
    workspaceId: string
    projectId: string
}

/**
 * Where a resolved context lands. The one place the mobile "project home" route is spelled
 * out — the root resolver and every `/w/...` index gate forward here.
 */
export const projectHomeUrl = ({workspaceId, projectId}: LastContext): string =>
    `/w/${encodeURIComponent(workspaceId)}/p/${encodeURIComponent(projectId)}/apps`

/** A website template link lands on that template's create step instead of the project home. */
export const projectTemplateUrl = ({workspaceId, projectId}: LastContext, templateKey: string) =>
    `/w/${encodeURIComponent(workspaceId)}/p/${encodeURIComponent(projectId)}/agents/new?template=${encodeURIComponent(templateKey)}`

const PENDING_TEMPLATE_KEY = "agenta:mobile:pending-template"
/** Long enough to sign up and verify an email; the desktop capture uses the same window. */
const PENDING_TEMPLATE_TTL_MS = 30 * 60 * 1000

/**
 * Keep a website template key across sign-in. The trip through `/auth` (and an OAuth provider)
 * drops the URL's query, so the `/m` root would otherwise land on the project home.
 */
export function rememberTemplateKey(key: string, now = Date.now()): void {
    try {
        localStorage.setItem(PENDING_TEMPLATE_KEY, JSON.stringify({key, capturedAt: now}))
    } catch {
        // storage unavailable (private mode / quota) — continuity is best-effort
    }
}

/**
 * The remembered template key, or "" when none is kept or it has expired. Reading does not
 * forget it: the `/m` root can resolve more than once while it settles (a remembered project,
 * then the fetched tree; React's development double run), and every run must still see the
 * key. The template screen forgets it once it has the key on its URL.
 */
export function peekTemplateKey(now = Date.now()): string {
    try {
        const raw = localStorage.getItem(PENDING_TEMPLATE_KEY)
        const parsed = raw ? (JSON.parse(raw) as {key?: unknown; capturedAt?: unknown}) : null
        if (
            parsed &&
            typeof parsed.key === "string" &&
            typeof parsed.capturedAt === "number" &&
            now - parsed.capturedAt <= PENDING_TEMPLATE_TTL_MS
        ) {
            return parsed.key.trim()
        }
        return ""
    } catch {
        return ""
    }
}

/** Forget the remembered template key; the template screen calls this once it has arrived. */
export function forgetTemplateKey(): void {
    try {
        localStorage.removeItem(PENDING_TEMPLATE_KEY)
    } catch {
        // storage unavailable — nothing was kept
    }
}

/** Settings -> LLM providers: where a key is added or a subscription signed in again. */
export const llmProvidersUrl = ({workspaceId, projectId}: LastContext): string =>
    `/w/${encodeURIComponent(workspaceId)}/p/${encodeURIComponent(projectId)}/settings?tab=llms`

export const billingUrl = ({workspaceId, projectId}: LastContext): string =>
    `/w/${encodeURIComponent(workspaceId)}/p/${encodeURIComponent(projectId)}/settings?tab=billing`

/**
 * The `/w/<segment>` a project routes under: its organization id. Workspace removal step 2
 * answers the organization id where a workspace id was, and during the rollout an older API
 * pod still answers the legacy workspace id for the same project, so routing keys on the
 * organization, which never changes. A row without one (older API) keeps its workspace id.
 */
export const projectRouteSegment = (project: {
    organization_id?: string | null
    workspace_id?: string | null
}): string | undefined => project.organization_id || project.workspace_id || undefined

const PROJECT_PATH = /^\/w\/([^/?#]+)\/p\/([^/?#]+)(.*)$/

/**
 * The same route with the project's organization id in the `/w/<segment>` part, or null when
 * the URL already names it (or the project is not in the list, or the list is not loaded).
 * A legacy workspace id in a bookmark or a link is rewritten once; the rewrite cannot loop,
 * because its result names the organization.
 */
export function canonicalProjectPath(
    asPath: string,
    projects: MobileProject[] | undefined,
): string | null {
    const match = PROJECT_PATH.exec(asPath)
    if (!match || !projects) return null
    const [, segment, projectSegment, rest] = match
    const projectId = decodeURIComponent(projectSegment)
    const project = projects.find((row) => row.project_id === projectId)
    const organizationId = project?.organization_id
    if (!organizationId || decodeURIComponent(segment) === organizationId) return null
    return `/w/${encodeURIComponent(organizationId)}/p/${projectSegment}${rest}`
}

export function writeLastContext(context: LastContext): void {
    try {
        localStorage.setItem(LAST_CONTEXT_KEY, JSON.stringify(context))
    } catch {
        // storage unavailable (private mode / quota) — continuity is best-effort
    }
}

/**
 * Forget the fast-path pair. Called when the stored project will not load, so `/m/` stops
 * forwarding into a route that cannot render. Safe to over-call: `ContextSync` rewrites the
 * pair on the next project that does load.
 */
export function clearLastContext(): void {
    try {
        localStorage.removeItem(LAST_CONTEXT_KEY)
    } catch {
        // storage unavailable (private mode / quota) — continuity is best-effort
    }
}

export function readLastContext(): LastContext | null {
    try {

}

/** Only gate top-level document navigations — never assets, fetches, or POSTs. */
export function isDocumentNavigation(input: Pick<GateInput, "method" | "header">): boolean {
    if (input.method !== "GET" && input.method !== "HEAD") return false
    const dest = input.header("sec-fetch-dest")
    if (dest) return dest === "document"
    return (input.header("accept") ?? "").includes("text/html")
}

/**
 * Desktop routes that must never redirect to /m (design.md documented
 * exceptions). /auth now maps to the mobile sign-in (→ /m/auth), EXCEPT
 * /auth/callback: an OAuth/SSO redirect landing must never be bounced mid-flow,
 * because the redirect URI is fixed at the provider. When the mobile app started
 * the flow (MOBILE_AUTH_CALLBACK_COOKIE) the landing is forwarded to the mirror
 * page under /m instead — see decideDesktopGate. /post-signup and
 * /workspaces/accept are permanently desktop-only.
 */
const AUTH_CALLBACK_RE = /^\/auth\/callback(\/|$)/

const AUTH_RE = /^\/auth(\/|$)/

/** The `/m` screen that accepts an invite; the invite itself waits in browser storage. */
const INVITE_ROUTE_RE = /^\/invite\/?$/

/** An emailed invite: `/auth` with a one-time token and its organization. A reset link has neither the path nor the organization. */
export function isInviteLink(pathname: string, search: string): boolean {
    if (!/^\/auth\/?$/.test(pathname)) return false
    const params = new URLSearchParams(search)
    return Boolean(params.get("token") && params.get("organization_id"))
}

/**
 * Any other `/auth` link carrying a one-time `token` (SuperTokens password reset) completes on
 * desktop.
 *
 * Redirecting it would drop the token twice over: `mapDesktopToMobile` returns a bare `/m/auth`,
 * and the mobile app has no screen that consumes one. Same reasoning as the OAuth callback
 * exception — a single-use credential must not be bounced.
 */
export function isTokenBearingAuthLink(pathname: string, search: string): boolean {
    if (!AUTH_RE.test(pathname) || isInviteLink(pathname, search)) return false
    return Boolean(new URLSearchParams(search).get("token"))
}

/**
 * An `/auth` link carrying `auth_error` completes on desktop, for the same reason as a token: the
 * param IS the payload. `web/oss/src/lib/api/assets/axiosConfig.ts` redirects a 403 here so the
 * user can finish required SSO or social re-authentication, and the desktop auth page reads it.
 * `mapDesktopToMobile` returns a bare `/m/auth`, so redirecting would drop the reason and leave
 * Where a signed-out visitor with no Classic mode preference signs in, or `null` to stay.
 *
 * Only the entry points move: bare `/w` (where `/` redirects) and `/auth`. A deep link keeps the
 * desktop sign-in, which returns the user to it (`?redirectToPath=`); `/m`'s sign-in always lands
 * on its home screen. A website template link goes to the `/m` root, which keeps the key across
 * sign-in; `/m/auth` would drop it.
 */
const signedOutEntryRoute = (pathname: string, search: string): string | null => {
    if (/^\/w\/?$/.test(pathname)) {
        const templateQuery = templateQueryFrom(search)
        return templateQuery ? `/m/${templateQuery}` : "/m/auth"
    }
    if (AUTH_RE.test(pathname) && !new URLSearchParams(search).has("redirectToPath")) {
        return "/m/auth"
    }
    return null
}

/** Forward gate: runs in the DESKTOP apps. Sees no /m traffic behind Traefik. */
export function decideDesktopGate(input: GateInput): GateDecision {
    try {
        // `?view=desktop` outranks everything below, including the callback handback: it is the
        // user saying "keep me here", and it must still win now that the callback check runs
        // before the flag.
        const wantsDesktop = new URLSearchParams(input.search).get(VIEW_PARAM) === "desktop"

        // A provider redirect the MOBILE app started has to reach /m. The cookie is an explicit intent set by /m moments earlier,
        // not a device heuristic, and the OAuth state lives in /m's same-origin sessionStorage.
        // Gating this would strand a mobile SSO sign-in on the desktop route, where the state it
        // needs does not exist.
        if (
            !wantsDesktop &&
            isDocumentNavigation(input) &&
            AUTH_CALLBACK_RE.test(input.pathname) &&
            input.cookie(MOBILE_AUTH_CALLBACK_COOKIE)
        ) {
            return {kind: "redirect", location: `/m${input.pathname}${input.search}`}
        }

        if (!isDocumentNavigation(input)) return {kind: "pass"}

        // Escape hatch: "View desktop site" links carry ?view=desktop. It opts out of BOTH
        // reasons to bounce — a user asking to stay here does not care which one sent them.
        if (wantsDesktop) {
            return {
                kind: "set-cookie-redirect",
                cookie: MOBILE_OPTOUT_COOKIE,
                clearCookie: MOBILE_OPTIN_COOKIE,
                location: stripViewParam(input.pathname, input.search),
            }
        }

        // Before the opt-out and Classic mode: an invite link only ever completes on /m.
        if (isInviteLink(input.pathname, input.search)) {
            return {kind: "redirect", location: `/m/auth${input.search}`}
        }

        // The mobile-started callback is handled above, before the flag.
        if (isDesktopOnlyLink(input.pathname, input.search)) return {kind: "pass"}
        if (input.cookie(MOBILE_OPTOUT_COOKIE)) return {kind: "pass"}

        // Classic mode ON is the user asking for the desktop app in as many words, through a
        // switch that exists to bring them here. It outranks the device heuristic, which is only
        // ever a guess about what they want. Without this the two fight and /m wins every time:
        // the switch sends them to /w, the device check sends them back, and on a phone there is
        // no way out of `/m` at all.
        const wantsClassic = input.cookie(CLASSIC_MODE_COOKIE) === "1"

        // Device: a phone gets /m for anything, mapped or not.
        if (!wantsClassic && isMobileDevice(input.header)) {
            return {kind: "redirect", location: mapDesktopToMobile(input.pathname, input.search)}
        }

        // Signed out, no preference: the cookie is only written after a sign-in, so without
        // this a new visitor signs up on the desktop app and never sees /m's onboarding.
        if (
            !input.cookie(CLASSIC_MODE_COOKIE) &&
            !SESSION_COOKIES.some((name) => input.cookie(name))
        ) {
            const location = signedOutEntryRoute(input.pathname, input.search)
            if (location) return {kind: "redirect", location}
        }

        // Preference: Classic mode off means live in /m — but only for pages /m actually has.
        if (input.cookie(CLASSIC_MODE_COOKIE) === "0") {
            const location = mobileRouteFor(input.pathname, input.search)
            if (location) return {kind: "redirect", location}
        }

        return {kind: "pass"}
    } catch {
        // Design rule: the gate never hard-fails — ambiguity falls through.
        return {kind: "pass"}
    }
}

/**
 * Reverse direction: runs in the MOBILE app. Sees only /m traffic behind Traefik.
 *
 * It never looks at the device: a desktop browser may open /m. It only returns a user who
 * turned Classic mode on to the desktop app.
 */
export function decideMobileGate(input: GateInput): GateDecision {
    try {
        if (!isDocumentNavigation(input)) return {kind: "pass"}

        // Escape hatch: "Open mobile version" links carry ?view=mobile.
        if (new URLSearchParams(input.search).get(VIEW_PARAM) === "mobile") {
            return {
                kind: "set-cookie-redirect",
                cookie: MOBILE_OPTIN_COOKIE,
                clearCookie: MOBILE_OPTOUT_COOKIE,
                location: stripViewParam(input.pathname, input.search),
            }
        }

        // An OAuth landing completes wherever it lands — bouncing it drops the
        // one-time code and strands the flow.
        if (AUTH_CALLBACK_RE.test(input.pathname)) return {kind: "pass"}
        // Same for an invite: the desktop route for it would drop the token.
        if (INVITE_ROUTE_RE.test(input.pathname) || isInviteLink(input.pathname, input.search)) {
            return {kind: "pass"}
        }
        if (input.cookie(MOBILE_OPTIN_COOKIE)) return {kind: "pass"}

        // The desktop gate ranks Classic mode above the device heuristic (`wantsClassic`), so a
        // user who asked for the full app is returned to it, phone included.
        if (input.cookie(CLASSIC_MODE_COOKIE) === "1") {
            return {kind: "redirect", location: mapMobileToDesktop(input.pathname, input.search)}
        }
        return {kind: "pass"}
    } catch {
        return {kind: "pass"}
    }
}
