async def send_invitation_email(
    email: str,
    token: str,
    project_id: str,
    workspace_id: str,
    organization_id: str,
    user: UserDB,
):
    """
    Sends an invitation email to the specified email address, containing a link to accept the invitation.

    Args:
        email (str): The email address to send the invitation to.
        token (str): The token to include in the invitation link.
        project_id (str): The ID of the project that the user is being invited to join.
        workspace_id (str): The ID of the workspace to which the user is being invited.
        organization_id (str): The ID of the organization to which the user is being invited.
        user (UserDB): The user who is sending the invitation.

    Returns:
        bool: True if the email was sent successfully, False otherwise.
    """

    token_param = quote(token, safe="")
    email_param = quote(email, safe="")
    org_param = quote(str(organization_id), safe="")
    workspace_param = quote(str(workspace_id), safe="")
    project_param = quote(project_id, safe="")

    invite_link = (
        f"{env.agenta.web_url}/m/auth"
        f"?token={token_param}"
        f"&email={email_param}"
        f"&organization_id={org_param}"
        f"&workspace_id={workspace_param}"
        f"&project_id={project_param}"
    )

    # If email delivery is not configured, return the link for manual sharing.
    if not (env.smtp.enabled or env.sendgrid.enabled):
        return invite_link

    await emailing.send_email(
        to_email=email,
        subject=f"{user.username} invited you to join their organization",
        username=user.username,
        action="invited you to join",
        workspace="their organization",
        call_to_action=(
            "Click the link below to accept the invitation:</p><br>"
            f'<a href="{invite_link}">Accept Invitation</a>'
        ),
    )
    return True


def resolve_workspace_invite_role(payload: InviteRequest) -> str:
    """Resolve the workspace role for an invite, defaulting to the catalog floor.

    Shared by OSS and EE invite paths. Validates against the effective workspace
    catalog (env-overridable via AGENTA_ACCESS_ROLES in EE) since the API model
    accepts any string for forward-compatibility with custom roles.
    """

    raw = payload.roles[0] if payload.roles else None
    role = getattr(raw, "value", None) or (str(raw) if raw is not None else None)
    # Get project by id
    project_db = await db_manager.get_project_by_id(project_id=project_id)

    # Send the invitation email
    send_email = await send_invitation_email(
        payload.email,
        invitation.token,  # type: ignore
        project_id=str(project_db.id),
        # The organization id where the link carries a workspace id (design D6).
        workspace_id=str(project_db.organization_id),
        organization_id=str(project_db.organization_id),
        user=user_performing_action,
    )

    if isinstance(send_email, str):
        return {"url": send_email}

    if not send_email:
        raise HTTPException(
            detail="Failed to invite user to organization",
            status_code=400,
        )

    return send_email


